DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM _merge.id_offset WHERE id_offset + src_max_id > 2147483647 LOOP
    RAISE EXCEPTION 'ID overflow: % from % would reach %', r.table_name, r.source_db, r.id_offset + r.src_max_id;
  END LOOP;
END $$;

